/*
 * Д-39. Заявление в банк о сохранении доходов в размере прожиточного минимума.
 * Основа: ч. 6 ст. 8 Закона № 229-ФЗ (заявление в банк, который обслуживает счета должника и исполняет требования
 * исполнительного документа о взыскании или аресте; ПМ сохраняется только на одном счёте), ч. 7 ст. 8 (что указать:
 * ФИО, гражданство, документ, место жительства или пребывания, телефон, реквизиты счёта в этом банке), ч. 8 ст. 8
 * (иждивенцы — через суд), ч. 3.1 ст. 99 (исключения), ч. 5.3 ст. 70. ПМ на 2026 год — 426-ФЗ (C.PM).
 * Статус: ЧЕРНОВИК, не проверен юристом.
 */
(function (global) {
  "use strict";
  const { U } = global.Engine;
  const C = global.Common;
  const F = U.F;

  function derive(a) {
    const regional = typeof a.region_pm === "number" && a.region_pm > C.PM.working ? a.region_pm : null;
    return { regional, excluded: ["alimony", "harm"].includes(a.what) };
  }

  const spec = {
    id: "d39",
    code: "Д-39",
    title: "Заявление в банк о сохранении прожиточного минимума",
    lead: "Взыскатель предъявил исполнительный лист или судебный приказ прямо в банк, и банк списывает все деньги. Заявление, чтобы на счёте каждый месяц оставался прожиточный минимум. Займёт около 5 минут.",
    status: "draft",

    steps: [
      {
        id: "bank", title: "Банк и долг",
        questions: [
          { id: "who", type: "choice", label: "Кто списывает деньги?", options: [
            { value: "bank", label: "Банк — по исполнительному листу или судебному приказу, который ему прислал взыскатель" },
            { value: "fssp", label: "Приставы — есть исполнительное производство", hint: "Тогда надёжнее подать заявление приставу" },
          ] },
          { id: "what", type: "choice", label: "Что с вас взыскивают?", options: [
            { value: "debt", label: "Долг: кредит, ЖКХ, налоги, штрафы и т. п." },
            { value: "alimony", label: "Алименты" },
            { value: "harm", label: "Возмещение вреда здоровью, по потере кормильца или ущерба от преступления" },
          ] },
          { id: "bank", type: "text", label: "Банк", placeholder: "ПАО Сбербанк" },
          { id: "bank_address", type: "text", label: "Адрес отделения", required: false },
          { id: "account", type: "text", label: "Номер счёта в этом банке, на котором сохранять деньги", hint: "20 цифр — в приложении банка в реквизитах счёта. Номер карты не подходит", placeholder: "40817810…",
            validate: v => /^\d{20}$/.test(String(v).replace(/\s/g, "")) ? null : "Номер счёта — 20 цифр" },
          { id: "doc", type: "text", label: "Исполнительный документ", required: false, hint: "Если знаете: что это, кто выдал, номер и дата", placeholder: "Судебный приказ мирового судьи участка № 5 по делу № 2-100/2026 от 01.06.2026" },
          { id: "creditor", type: "text", label: "Взыскатель", required: false },
          { id: "group", type: "choice", label: "К какой группе вы относитесь?", options: [
            { value: "working", label: "Трудоспособное население" },
            { value: "pension", label: "Пенсионер" },
          ] },
          { id: "region", type: "text", label: "Регион, где вы живёте", placeholder: "г. Москва" },
          { id: "region_pm", type: "money", label: "Прожиточный минимум в вашем регионе для вашей группы на 2026 год", suffix: "₽", required: false,
            hint: `Если он больше федерального (${U.money(C.PM.working)} ₽), сохраняют региональный. Не знаете — оставьте пустым` },
        ],
      },
      {
        id: "you", title: "Вы",
        questions: [
          { id: "buyer_name", type: "text", label: "Ваши фамилия, имя и отчество", autocomplete: "name" },
          { id: "citizenship", type: "text", label: "Гражданство", placeholder: "Российская Федерация" },
          { id: "passport", type: "text", label: "Паспорт: серия, номер, кем и когда выдан", hint: "Закон требует указать документ. Данные остаются в вашем браузере", placeholder: "45 12 345678, выдан ГУ МВД России по г. Москве 01.02.2020" },
          { id: "buyer_address", type: "text", label: "Адрес места жительства или пребывания", autocomplete: "street-address" },
          { id: "buyer_phone", type: "tel", label: "Телефон", autocomplete: "tel" },
        ],
      },
    ],

    derive,

    stop(a, d) {
      if (d.excluded) return { title: "По этому взысканию прожиточный минимум не сохраняется.", text: "Правило не применяется к алиментам, возмещению вреда здоровью, по потере кормильца и ущерба от преступления (ч. 3.1 ст. 99 Закона об исполнительном производстве)." };
      return null;
    },

    render(a, d) {
      const P = [];
      const T = t => P.push({ text: t, indent: true });
      P.push({ text: `В ${F(a.bank, "банк")}` + (a.bank_address ? `\nАдрес: ${a.bank_address}` : ""), align: "left", leftIndent: 4500, after: 120 });
      P.push({ text: `От: ${F(a.buyer_name, "ваши ФИО")}\nГражданство: ${F(a.citizenship, "гражданство")}\nПаспорт: ${F(a.passport, "паспорт")}\nАдрес: ${F(a.buyer_address, "адрес")}\nТел.: ${F(a.buyer_phone, "телефон")}`, align: "left", leftIndent: 4500, after: 360 });
      C.title(P, "ЗАЯВЛЕНИЕ", "о сохранении заработной платы и иных доходов ежемесячно в размере прожиточного минимума");
      T(`Банк исполняет в отношении меня требования исполнительного документа о взыскании денежных средств` + (a.doc ? ` (${a.doc}` + (a.creditor ? `, взыскатель — ${a.creditor})` : ")") : a.creditor ? ` (взыскатель — ${a.creditor})` : "") + ".");
      const pm = d.regional
        ? `прожиточного минимума, установленного в субъекте Российской Федерации по месту моего жительства (${F(a.region, "регион")}) для ${a.group === "pension" ? "пенсионеров" : "трудоспособного населения"}, — ${U.money(d.regional)} руб., поскольку он превышает прожиточный минимум трудоспособного населения в целом по Российской Федерации (${U.money(C.PM.working)} руб. на ${C.PM.year} год)`
        : `прожиточного минимума трудоспособного населения в целом по Российской Федерации (на ${C.PM.year} год — ${U.money(C.PM.working)} руб.), а если прожиточный минимум, установленный в субъекте Российской Федерации по месту моего жительства${a.region ? ` (${a.region})` : ""} для соответствующей социально-демографической группы населения, превышает эту величину, — в размере регионального прожиточного минимума`;
      T(`На основании ч. 6 и 7 ст. 8 Федерального закона от 02.10.2007 № 229-ФЗ «Об исполнительном производстве» прошу при обращении взыскания на мои доходы сохранять заработную плату и иные доходы ежемесячно в размере ${pm}.`);
      T(`Доходы в размере прожиточного минимума прошу сохранять на моём банковском счёте № ${F(a.account ? String(a.account).replace(/\s/g, "") : null, "номер счёта")}, открытом в вашем банке.`);
      C.sign(P, a);
      return P;
    },

    guidance(a) {
      const g = [
        { title: "Отдайте заявление в отделение банка и попросите отметку о приёме на вашем экземпляре.", text: "Многие банки принимают такое заявление и в приложении или на сайте — спросите в поддержке." },
        { title: "Прожиточный минимум сохраняется только на одном счёте.", text: "Если счета в нескольких банках, выберите один и переведите туда поступление зарплаты или пенсии." },
        { title: "Есть иждивенцы — больше минимума только через суд.", text: "Заявление подают в суд (ч. 8 ст. 8 Закона № 229-ФЗ)." },
      ];
      if (a.who === "fssp") g.unshift({ title: "Если деньги списывают по постановлению пристава, подайте заявление приставу (Д-38).", text: "Банк исполняет постановление пристава, и сохранение прожиточного минимума указывает пристав в своём постановлении." });
      return g;
    },

    fileName(a) { return "Заявление в банк о сохранении прожиточного минимума" + (a.buyer_name ? " — " + U.shortName(a.buyer_name) : ""); },
  };

  global.DOCS = global.DOCS || {};
  global.DOCS.d39 = spec;
})(typeof window !== "undefined" ? window : globalThis);
